-- aiPolytrack on Supabase: tables, security rules and server functions.
--
-- Paste this whole file into Supabase > SQL Editor > New query > Run.
-- It is safe to run again (after an update): it only creates what is
-- missing and replaces functions and policies with the current versions.
--
-- Everything that must not be trusted to a player's own browser runs here,
-- inside the database: invite codes, best times only ever getting faster,
-- credit balances, run tickets, recording checks, devices and bans.

-- ------------------------------------------------------------------ tables

-- no longer used for admin access (see admin_login below); kept so old
-- data and policies stay valid
create table if not exists public.admins (
  user_id uuid primary key
);

-- the admin page's sign-ins: a hash of each session token, for 12 hours
create table if not exists public.admin_sessions (
  token_hash text primary key,
  expires_at timestamptz not null
);
-- wrong admin passwords in the last 15 minutes (too many locks the login)
create table if not exists public.admin_login_fails (
  at timestamptz not null default now()
);

-- daily maps: how many paid attempts each player made on each day, and
-- each day's winner once it has been settled
create table if not exists public.daily_entries (
  uid uuid not null,
  day text not null,
  attempts integer not null default 0,
  primary key (uid, day)
);
create table if not exists public.daily_results (
  day text primary key,
  uid uuid,
  display_name text,
  time_ms integer,
  settled_at timestamptz not null default now()
);

-- small key/value settings: 'invite' {code}, 'admin_passcode' {salt, passHash},
-- 'notice' {menu, login} (the messages on the game's menu and sign-in screen)
create table if not exists public.settings (
  key text primary key,
  value jsonb not null
);

-- one row per player. legacy = moved over from Firebase and not yet
-- claimed by a new login (it keeps its times on the boards meanwhile)
create table if not exists public.profiles (
  id uuid primary key,
  display_name text not null,
  banned boolean not null default false,
  legacy boolean not null default false,
  created_at timestamptz not null default now()
);
create unique index if not exists profiles_name_ci on public.profiles (lower(display_name));

create table if not exists public.bests (
  uid uuid not null,
  course_id text not null,
  display_name text not null,
  banned boolean not null default false,
  time_ms integer not null check (time_ms > 0 and time_ms < 600000),
  updated_ms bigint not null default 0,
  primary key (uid, course_id)
);
create index if not exists bests_course on public.bests (course_id);

create table if not exists public.ghosts (
  uid uuid not null,
  course_id text not null,
  time_ms integer not null,
  samples text not null check (length(samples) < 400000),
  v smallint not null default 2,
  primary key (uid, course_id)
);

create table if not exists public.credit_events (
  id bigserial primary key,
  uid uuid not null,
  delta numeric not null,
  kind text not null,
  race_id text,
  note text,
  legacy_id text unique,          -- the Firebase document it came from
  created_at timestamptz not null default now()
);
create index if not exists credit_events_uid on public.credit_events (uid);

create table if not exists public.car_customization (
  uid uuid primary key,
  unlocked jsonb not null default '[]',
  primary_color jsonb not null,
  secondary_color jsonb not null,
  updated_at timestamptz not null default now()
);

create table if not exists public.run_log (
  id bigserial primary key,
  uid uuid not null,
  display_name text,
  kind text,
  course_id text,
  outcome text,
  time_ms integer,
  data jsonb not null default '{}',
  legacy_id text unique,
  created_at timestamptz not null default now()
);
create index if not exists run_log_created on public.run_log (created_at desc);

create table if not exists public.season_awards (
  season text primary key,
  data jsonb not null default '{}'
);

-- who brought whom: a player who signed up from a friend's link
create table if not exists public.referrals (
  uid uuid primary key,
  referrer uuid not null,
  at timestamptz not null default now()
);
create index if not exists referrals_referrer on public.referrals (referrer, at);

create table if not exists public.admin_notes (
  uid uuid primary key,
  real_name text not null,
  updated_at timestamptz not null default now()
);

create table if not exists public.races (
  id text primary key,
  state text not null check (state in ('lobby', 'starting', 'running', 'settled')),
  course_id text,
  created_at timestamptz not null default now(),
  created_by uuid,
  join_deadline timestamptz,
  started_at timestamptz,
  ends_at timestamptz,
  settled_by uuid
);
create index if not exists races_created on public.races (created_at desc);

create table if not exists public.race_entries (
  race_id text not null references public.races (id) on delete cascade,
  uid uuid not null,
  display_name text not null,
  buy_in integer not null check (buy_in > 0),
  attempts integer[] not null default '{}',
  best_time_ms integer,
  placement integer,
  payout integer,
  primary key (race_id, uid)
);

-- Firebase uid -> the placeholder id its data lives under until claimed.
-- deleted: the admin removed that player, so importing again leaves them out
create table if not exists public.legacy_ids (
  old_uid text primary key,
  new_id uuid not null unique default gen_random_uuid()
);
alter table public.legacy_ids add column if not exists deleted boolean not null default false;

-- ---------------------------------------------------------- security
-- The admin logins: a username and a bcrypt hash of its password. Set with
-- public.admin_set_login(...) in the Supabase SQL Editor only (no player or
-- browser can call it). The password itself is never stored.
create table if not exists public.admin_accounts (
  username text primary key,
  hash text not null,
  created_at timestamptz not null default now()
);
alter table public.admin_sessions add column if not exists username text;
alter table public.admin_login_fails add column if not exists ip text;
alter table public.admin_login_fails add column if not exists username text;
-- the old fixed logins and game-account admins are gone: only
-- admin_accounts can sign in, and sessions from before go with them
delete from public.admins where true;
delete from public.admin_sessions s where s.username is null
  or not exists (select 1 from public.admin_accounts a where a.username = s.username);

-- What the server knows about each map: where a run starts and finishes,
-- how big the finish gate is, and the fastest time it will believe
-- (floor_ms: 70% of the test driver's best, a lap no car can drive). ref_ms
-- is the test driver's best, len_m the road's length. Dailies are listed by day.
create table if not exists public.course_rules (
  course_id text primary key,
  sx real not null, sy real not null, sz real not null,
  fx real not null, fy real not null, fz real not null,
  gate_r real not null,
  floor_ms integer not null,
  ref_ms integer,
  len_m integer,
  cps real[]                      -- checkpoints every ~40 m: x, z, half width
);
alter table public.course_rules add column if not exists cps real[];

-- A computer, as far as a browser can tell: a random id the game keeps in
-- the browser (id) and a fingerprint of the browser and screen (fp). The
-- fingerprint is the same on identical school computers, so it is only a
-- hint; blocking is done by id (or by fingerprint/IP when the admin chooses).
create table if not exists public.devices (
  id text primary key check (id ~ '^[a-f0-9]{32}$'),
  fp text,
  first_ip text,
  last_ip text,
  first_seen timestamptz not null default now(),
  last_seen timestamptz not null default now()
);
create table if not exists public.device_accounts (
  device_id text not null,
  uid uuid not null,
  first_seen timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  primary key (device_id, uid)
);
create index if not exists device_accounts_uid on public.device_accounts (uid);
-- every account created, with the computer and network it came from
create table if not exists public.signup_log (
  id bigserial primary key,
  at timestamptz not null default now(),
  uid uuid,
  device_id text,
  fp text,
  ip text
);
create index if not exists signup_log_device on public.signup_log (device_id);
create index if not exists signup_log_ip on public.signup_log (ip, at);
-- blocked computers ('device'), browser fingerprints ('fp') or networks ('ip')
create table if not exists public.bans (
  kind text not null check (kind in ('device', 'fp', 'ip')),
  value text not null,
  note text,
  created_at timestamptz not null default now(),
  primary key (kind, value)
);

-- Every run gets a ticket from the server the moment the car sets off. A
-- time is only taken with its ticket, from the same player, on the same
-- map, after at least as long as the time itself has really passed.
create table if not exists public.runs (
  id uuid primary key default gen_random_uuid(),
  uid uuid not null,
  course_id text not null,
  device_id text,
  ip text,
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  time_ms integer,
  status text not null default 'open' check (status in ('open', 'done', 'void')),
  counted boolean not null default false,
  focus smallint,
  paid boolean not null default false,
  best_used boolean not null default false
);
create index if not exists runs_uid on public.runs (uid, started_at desc);
create index if not exists runs_device on public.runs (device_id, started_at desc);
create index if not exists runs_started on public.runs (started_at);

-- why a best looked unusual (only the admin reads this)
create table if not exists public.best_flags (
  uid uuid not null,
  course_id text not null,
  time_ms integer not null,
  flags text[] not null,
  run_id uuid,
  at timestamptz not null default now(),
  primary key (uid, course_id)
);

-- daily maps: attempts actually started, and payouts held for review
alter table public.daily_entries add column if not exists used integer not null default 0;
alter table public.daily_results add column if not exists held boolean not null default false;
alter table public.daily_results add column if not exists paid boolean;
create index if not exists run_log_uid on public.run_log (uid, created_at);

