-- ----------------------------------------------------------------- helpers

-- the address a username signs in with (must match the game's USERNAME_DOMAIN)
create or replace function public.login_email(p_name text) returns text
language sql immutable as $$ select lower(p_name) || '@chat7689.github.io' $$;

-- the database clock, so every game counts race deadlines the same way
create or replace function public.server_ms() returns bigint
language sql volatile as $$ select (extract(epoch from clock_timestamp()) * 1000)::bigint $$;

-- The admin page signs in with an admin_accounts login (see admin_login)
-- and then sends its session token with every request, in the
-- x-admin-token header. That is the only way in: a player's own login,
-- whoever they are, is never an admin.
create or replace function public._token_hash(p text) returns text
language sql immutable as $$ select encode(sha256(convert_to(coalesce(p, ''), 'UTF8')), 'hex') $$;

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.admin_sessions s join public.admin_accounts a on a.username = s.username
    where s.token_hash = public._token_hash(nullif(current_setting('request.headers', true), '')::json ->> 'x-admin-token')
      and s.expires_at > now())
$$;

-- ------------------------------------------------------------ admin login
-- Signs in with an admin_accounts login. Returns {token, user} or {error}:
-- never raises, so a wrong try is recorded. Ten wrong tries from one
-- network in 15 minutes lock that network out (others can still sign in);
-- 100 from everywhere lock it for everyone.
create or replace function public.admin_login(p_user text, p_password text) returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare tok text; u text := lower(btrim(coalesce(p_user, ''))); h text; v_ip text := public._client_ip();
begin
  delete from public.admin_login_fails where at < now() - interval '15 minutes';
  if (select count(*) from public.admin_login_fails where ip = v_ip) >= 10
     or (select count(*) from public.admin_login_fails) >= 100 then
    return jsonb_build_object('error', 'Too many wrong tries. Wait 15 minutes and try again.');
  end if;
  select a.hash into h from public.admin_accounts a where a.username = u;
  if h is null or extensions.crypt(coalesce(p_password, ''), h) <> h then
    insert into public.admin_login_fails (ip, username) values (v_ip, left(u, 64));
    return jsonb_build_object('error', 'That username and password do not match.');
  end if;
  delete from public.admin_sessions where expires_at < now();
  tok := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.admin_sessions (token_hash, expires_at, username) values (public._token_hash(tok), now() + interval '12 hours', u);
  return jsonb_build_object('token', tok, 'user', u);
end $$;

-- Sets THE admin login: every other admin login and every admin session is
-- removed. Run it yourself in Supabase > SQL Editor:
--   select public.admin_set_login('your-username', 'your password');
-- No player, browser or admin page can call it.
create or replace function public.admin_set_login(p_user text, p_password text) returns text
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare u text := lower(btrim(coalesce(p_user, '')));
begin
  if u !~ '^[a-z0-9_.-]{3,32}$' then raise exception 'Pick a username of 3-32 letters, numbers, dots, dashes or underscores.'; end if;
  if length(coalesce(p_password, '')) < 12 then raise exception 'Use a password of at least 12 characters.'; end if;
  delete from public.admin_sessions where true;
  delete from public.admin_accounts where true;
  insert into public.admin_accounts (username, hash) values (u, extensions.crypt(p_password, extensions.gen_salt('bf', 12)));
  return 'Admin login set for ' || u || '. Every other admin login and session is gone.';
end $$;

-- Ends a season: its final podium (most maps finished, then the lowest
-- total of best times, banned players left out) is kept for good as the
-- season_awards row 'final:<label>', which the game's menu shows as last
-- season's champion. Run it yourself in Supabase > SQL Editor just before
-- the new season's maps go live, with that season's map ids, e.g.
--   select public.close_season('Season 1', array['s2c1', 's2c29', ...]);
-- Running it again replaces that season's podium.
create or replace function public.close_season(p_label text, p_courses text[]) returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare v jsonb;
begin
  if coalesce(btrim(p_label), '') = '' or coalesce(array_length(p_courses, 1), 0) = 0 then
    raise exception 'Give the season a name and its map ids.';
  end if;
  with b as (
    select b.uid, count(*)::int as c, sum(b.time_ms)::bigint as tot
    from public.bests b
    where b.course_id = any(p_courses) and not b.banned
      and not exists (select 1 from public.profiles p where p.id = b.uid and p.banned)
    group by b.uid
  ), r as (
    select b.*, coalesce((select p.display_name from public.profiles p where p.id = b.uid), 'Driver') as n
    from b order by c desc, tot asc limit 3
  )
  select jsonb_build_object('label', btrim(p_label), 'maps', array_length(p_courses, 1),
    'closed_at', (extract(epoch from now()) * 1000)::bigint,
    'podium', coalesce(jsonb_agg(jsonb_build_object('uid', uid, 'n', n, 'count', c, 'total_ms', tot) order by c desc, tot asc), '[]'::jsonb))
  into v from r;
  insert into public.season_awards (season, data) values ('final:' || btrim(p_label), v)
  on conflict (season) do update set data = excluded.data;
  return v;
end $$;

-- signing out ends this token's session
create or replace function public.admin_logout() returns void
language sql volatile security definer set search_path = public, pg_temp as $$
  delete from public.admin_sessions
  where token_hash = public._token_hash(nullif(current_setting('request.headers', true), '')::json ->> 'x-admin-token')
$$;

-- the calling player's profile; refuses anyone not signed in, without a
-- profile, or banned
create or replace function public._player() returns public.profiles
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare p public.profiles;
begin
  if auth.uid() is null then raise exception 'not signed in' using errcode = '28000'; end if;
  select * into p from public.profiles where id = auth.uid();
  if not found then raise exception 'no profile' using errcode = '28000'; end if;
  if p.banned then raise exception 'This account is suspended.' using errcode = 'P0001'; end if;
  return p;
end $$;

create or replace function public._balance(p_uid uuid) returns integer
language sql stable security definer set search_path = public, pg_temp as $$
  select floor(coalesce(sum(delta), 0) + 0.000000001)::integer from public.credit_events where uid = p_uid
$$;

create or replace function public.valid_hsl(c jsonb) returns boolean
language sql immutable as $$
  select jsonb_typeof(c) = 'object'
    and (select count(*) from jsonb_object_keys(c)) = 3
    and jsonb_typeof(c -> 'h') = 'number' and (c ->> 'h')::numeric between 0 and 360
    and jsonb_typeof(c -> 's') = 'number' and (c ->> 's')::numeric between 0 and 100
    and jsonb_typeof(c -> 'l') = 'number' and (c ->> 'l')::numeric between 0 and 100
$$;

-- ---------------------------------------------------------- account setup

-- Moves everything held under a legacy placeholder id to a real login.
create or replace function public._adopt(p_from uuid, p_to uuid, p_name text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if p_from = p_to then return; end if;
  delete from public.profiles where id = p_to and legacy;           -- never happens, but never collide
  update public.profiles set id = p_to, legacy = false, display_name = p_name where id = p_from;
  update public.bests set uid = p_to, display_name = p_name where uid = p_from;
  update public.ghosts set uid = p_to where uid = p_from;
  update public.credit_events set uid = p_to where uid = p_from;
  update public.car_customization set uid = p_to where uid = p_from
    and not exists (select 1 from public.car_customization where uid = p_to);
  delete from public.car_customization where uid = p_from;
  update public.admin_notes set uid = p_to where uid = p_from
    and not exists (select 1 from public.admin_notes where uid = p_to);
  delete from public.admin_notes where uid = p_from;
  update public.run_log set uid = p_to where uid = p_from;
  update public.race_entries set uid = p_to where uid = p_from;
  update public.season_awards set data = replace(data::text, p_from::text, p_to::text)::jsonb
    where data::text like '%' || p_from::text || '%';
  update public.legacy_ids set new_id = p_to where new_id = p_from;
end $$;

-- Whether a name belongs to a player from before the move who has not
-- signed up again yet, so the sign-in page can tell them to (their old
-- password is not here). Asked before anyone is signed in.
create or replace function public.returning_player(p_name text) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from public.profiles where legacy and lower(display_name) = lower(trim(coalesce(p_name, ''))))
$$;

-- ------------------------------------------------------------- times

create or replace function public.reset_my_scores() returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if auth.uid() is null then raise exception 'not signed in' using errcode = '28000'; end if;
  delete from public.bests where uid = auth.uid();
  delete from public.ghosts where uid = auth.uid();
end $$;

-- ------------------------------------------------------------- credits

create or replace function public.my_balance() returns integer
language sql stable security definer set search_path = public, pg_temp as $$
  select public._balance(auth.uid())
$$;

-- a colour pack: 10 credits, only if the player has them
create or replace function public.buy_color() returns integer
language plpgsql security definer set search_path = public, pg_temp as $$
declare p public.profiles := public._player();
begin
  perform pg_advisory_xact_lock(hashtext('credits:' || p.id::text));
  if public._balance(p.id) < 10 then raise exception 'You need 10 credits for a color.' using errcode = 'P0001'; end if;
  insert into public.credit_events (uid, delta, kind) values (p.id, -10, 'color');
  return public._balance(p.id);
end $$;

-- ------------------------------------------------------------ daily maps
-- A new map every day (the game makes it from the date), open from 00:00 to
-- 12:00 Pacific time. Each attempt costs 1 credit. At noon the fastest wins
-- 1 000 credits: whichever player's game first asks after 12:05 (the five
-- minutes let runs still on the road finish) settles it, exactly once.
create or replace function public._daily_now() returns timestamp
language sql stable as $$ select (now() at time zone 'America/Los_Angeles') $$;
create or replace function public._daily_today() returns text
language sql stable as $$ select to_char(public._daily_now(), 'YYYYMMDD') $$;
-- may an attempt start on day d now? (that day, before noon)
create or replace function public._daily_open(d text) returns boolean
language sql stable as $$ select d = public._daily_today() and extract(hour from public._daily_now()) < 12 $$;
-- may a time for day d be saved now? (until 12:05)
create or replace function public._daily_accepts(d text) returns boolean
language sql stable as $$
  select d ~ '^[0-9]{8}$' and public._daily_now() >= to_date(d, 'YYYYMMDD')::timestamp
     and public._daily_now() < to_date(d, 'YYYYMMDD')::timestamp + interval '12 hours 5 minutes'
$$;

create or replace function public.start_daily_attempt(p_day text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare p public.profiles := public._player(); bal integer;
begin
  perform pg_advisory_xact_lock(hashtext('credits:' || p.id::text));
  bal := public._balance(p.id);
  if not public._daily_open(coalesce(p_day, '')) then
    return jsonb_build_object('ok', false, 'error', 'closed', 'balance', bal);
  end if;
  if bal < 1 then return jsonb_build_object('ok', false, 'error', 'credits', 'balance', bal); end if;
  insert into public.credit_events (uid, delta, kind, note) values (p.id, -1, 'daily', 'attempt ' || p_day);
  insert into public.daily_entries (uid, day, attempts) values (p.id, p_day, 1)
    on conflict (uid, day) do update set attempts = public.daily_entries.attempts + 1;
  return jsonb_build_object('ok', true, 'balance', bal - 1,
    'attempts', (select attempts from public.daily_entries where uid = p.id and day = p_day));
end $$;

create or replace function public.settle_daily(p_day text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare w record; r public.daily_results; hold boolean;
begin
  if coalesce(p_day, '') !~ '^[0-9]{8}$' then raise exception 'bad day' using errcode = '22023'; end if;
  if public._daily_now() < to_date(p_day, 'YYYYMMDD')::timestamp + interval '12 hours 5 minutes' then
    return jsonb_build_object('settled', false);
  end if;
  perform pg_advisory_xact_lock(hashtext('daily:' || p_day));
  select * into r from public.daily_results where day = p_day;
  if found then return to_jsonb(r) || jsonb_build_object('settled', true); end if;
  select b.uid, b.display_name, b.time_ms into w from public.bests b
    where b.course_id = 'd' || p_day and not b.banned order by b.time_ms, b.updated_ms limit 1;
  -- a winning time with anything unusual about it waits for the admin
  hold := w.uid is not null and (not exists (select 1 from public.course_rules where course_id = 'd' || p_day)
          or exists (select 1 from public.best_flags f where f.uid = w.uid and f.course_id = 'd' || p_day));
  insert into public.daily_results (day, uid, display_name, time_ms, held, paid)
    values (p_day, w.uid, w.display_name, w.time_ms, hold, case when w.uid is null then null else not hold end)
    returning * into r;
  if r.uid is not null and not hold then
    insert into public.credit_events (uid, delta, kind, note) values (r.uid, 1000, 'daily_win', 'won daily ' || p_day);
  end if;
  return to_jsonb(r) || jsonb_build_object('settled', true);
end $$;

-- ------------------------------------------------- devices and networks

-- The caller's network address as the API saw it (best effort: Cloudflare's
-- header first, then the proxies'). Empty when unknown.
create or replace function public._client_ip() returns text
language sql stable as $$
  select left(coalesce(nullif(btrim(h ->> 'cf-connecting-ip'), ''), nullif(btrim(h ->> 'x-real-ip'), ''),
                       nullif(btrim(split_part(h ->> 'x-forwarded-for', ',', 1)), ''), ''), 64)
  from (select coalesce(nullif(current_setting('request.headers', true), ''), '{}')::json as h) x
$$;

-- is this computer, browser or network blocked?
create or replace function public._blocked(p_device text, p_fp text, p_ip text) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from public.bans b where (b.kind = 'device' and b.value = coalesce(p_device, ''))
                                              or (b.kind = 'fp' and b.value = coalesce(p_fp, ''))
                                              or (b.kind = 'ip' and b.value = coalesce(p_ip, '') and p_ip <> ''))
$$;

-- remembers the computer (and which account used it); returns whether it is blocked
create or replace function public._see_device(p_device text, p_fp text) returns boolean
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_ip text := public._client_ip(); v_fp text := left(coalesce(p_fp, ''), 64);
begin
  if coalesce(p_device, '') !~ '^[a-f0-9]{32}$' then return public._blocked(null, v_fp, v_ip); end if;
  insert into public.devices (id, fp, first_ip, last_ip) values (p_device, v_fp, v_ip, v_ip)
    on conflict (id) do update set fp = excluded.fp, last_ip = excluded.last_ip, last_seen = now();
  if auth.uid() is not null then
    insert into public.device_accounts (device_id, uid) values (p_device, auth.uid())
      on conflict (device_id, uid) do update set last_seen = now();
  end if;
  return public._blocked(p_device, v_fp, v_ip);
end $$;

-- the game says which computer a signed-in player is on
create or replace function public.touch_device(p_device text, p_fp text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if auth.uid() is null then raise exception 'not signed in' using errcode = '28000'; end if;
  return jsonb_build_object('blocked', public._see_device(p_device, p_fp));
end $$;

-- ----------------------------------------------------------------- runs

-- A ticket for a run, asked for the moment the car sets off. One run at a
-- time per player (a new one ends the last) and per computer, a sane number
-- per hour, nothing from a browser driven by a script, nothing from a
-- blocked computer. A daily run uses up one paid attempt.
create or replace function public.start_run(p_course text, p_device text, p_fp text, p_auto boolean default false) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare p public.profiles := public._player(); rid uuid; v_ip text := public._client_ip(); dd text;
begin
  if coalesce(p_auto, false) then
    return jsonb_build_object('ok', false, 'error', 'auto', 'message', 'Times can''t be set from a browser that is being controlled by a script.');
  end if;
  if public._see_device(p_device, p_fp) then
    return jsonb_build_object('ok', false, 'error', 'blocked', 'message', 'This computer is blocked from setting times.');
  end if;
  if coalesce(p_device, '') !~ '^[a-f0-9]{32}$' then
    return jsonb_build_object('ok', false, 'error', 'device', 'message', 'Reload the game to set times.');
  end if;
  perform pg_advisory_xact_lock(hashtext('run:' || p.id::text));
  if coalesce(p_course, '') ~ '^d[0-9]{8}$' then
    dd := substr(p_course, 2);
    if not public._daily_open(dd) then
      return jsonb_build_object('ok', false, 'error', 'closed', 'message', 'Today''s daily has closed.');
    end if;
    update public.daily_entries set used = used + 1 where uid = p.id and day = dd and used < attempts;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'unpaid', 'message', 'Each daily attempt costs 1 credit: start it from the Daily screen.');
    end if;
  elsif not exists (select 1 from public.course_rules where course_id = p_course) then
    return jsonb_build_object('ok', false, 'error', 'course', 'message', 'That map doesn''t take times.');
  end if;
  if (select count(*) from public.runs where uid = p.id and started_at > now() - interval '1 hour') >= 1500
     or (select count(*) from public.runs where device_id = p_device and started_at > now() - interval '1 hour') >= 2500 then
    return jsonb_build_object('ok', false, 'error', 'rate', 'message', 'Too many runs in the last hour. Take a break and come back.');
  end if;
  -- a new run ends this player's last one
  update public.runs set status = 'void' where uid = p.id and status = 'open';
  -- another account already driving on this computer
  if exists (select 1 from public.runs where device_id = p_device and status = 'open' and uid <> p.id
             and started_at > now() - interval '3 minutes') then
    return jsonb_build_object('ok', false, 'error', 'busy', 'message', 'Another account is already driving on this computer. One game at a time.');
  end if;
  insert into public.runs (uid, course_id, device_id, ip) values (p.id, p_course, p_device, v_ip) returning id into rid;
  -- old tickets go after two weeks
  delete from public.runs where id in (select id from public.runs where started_at < now() - interval '14 days' limit 200);
  return jsonb_build_object('ok', true, 'run', rid);
end $$;

-- The finish: the time has to fit the real time since the ticket, be no
-- faster than the map allows, and come from a game window that was in
-- focus. A season run then pays its +1 credit (at most one every 10 s),
-- and the first finish of a map pays FIRST_FINISH_BONUS once: "first" means
-- no best on that map yet (the best goes up after this check) and the
-- bonus never paid for it before. Every counted finish also counts toward
-- the daily challenge: the 300th of a day (midnight to midnight Pacific,
-- like the daily map) pays 300 more, once a day.
create or replace function public.finish_run(p_run uuid, p_time_ms integer, p_focus integer, p_auto boolean default false) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare p public.profiles := public._player(); r public.runs; el numeric; fl integer; credited boolean := false; bonus integer := 0;
  day_runs integer := 0; day_bonus integer := 0; d text := to_char(now() at time zone 'America/Los_Angeles', 'YYYYMMDD');
begin
  select * into r from public.runs where id = p_run and uid = p.id for update;
  if not found then return jsonb_build_object('ok', false, 'message', 'This run wasn''t registered with the server, so the time stays on this device only.'); end if;
  if r.status <> 'open' then return jsonb_build_object('ok', false, 'message', 'This run was replaced by a newer one.'); end if;
  el := extract(epoch from (now() - r.started_at)) * 1000;
  if p_time_ms is null or p_time_ms <= 0 or p_time_ms >= 600000 or p_time_ms > el + 1500 or el > p_time_ms + 120000 then
    update public.runs set status = 'void', ended_at = now(), time_ms = p_time_ms where id = r.id;
    return jsonb_build_object('ok', false, 'message', 'That time doesn''t match how long the run really took.');
  end if;
  select floor_ms into fl from public.course_rules where course_id = r.course_id;
  if p_time_ms < coalesce(fl, 12000) then
    update public.runs set status = 'void', ended_at = now(), time_ms = p_time_ms where id = r.id;
    return jsonb_build_object('ok', false, 'message', 'That time is faster than the map allows.');
  end if;
  if coalesce(p_auto, false) then
    update public.runs set status = 'void', ended_at = now(), time_ms = p_time_ms where id = r.id;
    return jsonb_build_object('ok', false, 'message', 'Times can''t be set from a browser that is being controlled by a script.');
  end if;
  if coalesce(p_focus, 0) < 85 then
    update public.runs set status = 'done', counted = false, ended_at = now(), time_ms = p_time_ms, focus = p_focus where id = r.id;
    return jsonb_build_object('ok', false, 'message', 'Not counted: the game window wasn''t in focus for the run.');
  end if;
  update public.runs set status = 'done', counted = true, ended_at = now(), time_ms = p_time_ms, focus = p_focus where id = r.id;
  if r.course_id !~ '^d[0-9]{8}$' then
    perform pg_advisory_xact_lock(hashtext('credits:' || p.id::text));
    if not exists (select 1 from public.credit_events where uid = p.id and kind = 'grind' and created_at > now() - interval '10 seconds') then
      insert into public.credit_events (uid, delta, kind, note) values (p.id, 1, 'grind', 'run ' || r.id::text);
      update public.runs set paid = true where id = r.id;
      credited := true;
    end if;
    if not exists (select 1 from public.bests where uid = p.id and course_id = r.course_id)
       and not exists (select 1 from public.credit_events where uid = p.id and kind = 'first_finish' and note = 'map ' || r.course_id) then
      bonus := 100;
      insert into public.credit_events (uid, delta, kind, note) values (p.id, bonus, 'first_finish', 'map ' || r.course_id);
    end if;
  end if;
  day_runs := public._day_runs(p.id);
  if day_runs >= 300 then
    perform pg_advisory_xact_lock(hashtext('credits:' || p.id::text));
    if not exists (select 1 from public.credit_events where uid = p.id and kind = 'daily_runs' and note = 'day ' || d) then
      day_bonus := 300;
      insert into public.credit_events (uid, delta, kind, note) values (p.id, day_bonus, 'daily_runs', 'day ' || d);
    end if;
  end if;
  return jsonb_build_object('ok', true, 'credited', credited, 'bonus', bonus, 'day_runs', day_runs, 'day_bonus', day_bonus,
    'balance', public._balance(p.id));
end $$;

-- A run's recording against the map: the right number of samples for the
-- time, starting at the start and ending in the finish gate, no jumps
-- faster than any car goes, no more boost than the tank holds. Returns
-- {ok, error} and flags for anything unusual the admin should see.
create or replace function public._ghost_check(p_course text, p_time_ms integer, p_samples text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  a float8[]; n integer; need integer; r public.course_rules; i integer; k integer;
  dx float8; dz float8; v float8; vmax float8 := 0; boost integer := 0; tog integer := 0;
  s integer; prev integer := -1; ax float8; az float8; hi integer := 0; flags text[] := '{}';
  j integer; fr integer; bi integer; best float8; cx float8; cz float8; hw float8;
  bad constant text := 'The run''s recording doesn''t match the time, so it can''t go on the leaderboard.';
begin
  if p_samples is null or length(p_samples) < 16 then
    return jsonb_build_object('ok', false, 'error', 'This run has no recording, so it can''t go on the leaderboard.');
  end if;
  begin
    a := string_to_array(p_samples, ',')::float8[];
  exception when others then
    return jsonb_build_object('ok', false, 'error', bad);
  end;
  if a is null or array_length(a, 1) % 8 <> 0 then return jsonb_build_object('ok', false, 'error', bad); end if;
  if exists (select 1 from unnest(a) x where x = 'NaN'::float8 or x = 'Infinity'::float8 or x = '-Infinity'::float8) then
    return jsonb_build_object('ok', false, 'error', bad);
  end if;
  n := array_length(a, 1) / 8;
  need := ceil(p_time_ms * 20 / 1000.0)::integer;
  if p_time_ms < 290000 and (n < need - 1 or n > need + 4) then return jsonb_build_object('ok', false, 'error', bad); end if;
  for i in 2..n loop
    k := (i - 1) * 8;
    dx := a[k + 1] - a[k - 7]; dz := a[k + 3] - a[k - 5];
    v := sqrt(dx * dx + dz * dz) * 20;
    if v > vmax then vmax := v; end if;
  end loop;
  -- 66 m/s is the fastest any test run went (downhill, boosting); 100 is a teleport
  if vmax > 100 then return jsonb_build_object('ok', false, 'error', bad); end if;
  if vmax > 75 then flags := array_append(flags, 'speed'); end if;
  for i in 1..n loop
    s := a[(i - 1) * 8 + 8]::integer;
    if s & 16 <> 0 then boost := boost + 1; end if;
    if prev >= 0 and (s & 12) <> (prev & 12) then tog := tog + 1; end if;
    prev := s;
  end loop;
  -- the tank holds 3 seconds of boost
  if boost > 3.4 * 20 then return jsonb_build_object('ok', false, 'error', bad); end if;
  -- steering switched more than 7 times a second, all run long
  if p_time_ms > 5000 and tog / (p_time_ms / 1000.0) > 7 then flags := array_append(flags, 'inputs'); end if;
  -- sideways jolts beyond anything the test runs showed (crashes reach ~100 m/s2)
  for i in 4..(n - 3) loop
    ax := (a[(i + 2) * 8 + 1] - 2 * a[(i - 1) * 8 + 1] + a[(i - 4) * 8 + 1]) / 0.0225;
    az := (a[(i + 2) * 8 + 3] - 2 * a[(i - 1) * 8 + 3] + a[(i - 4) * 8 + 3]) / 0.0225;
    if sqrt(ax * ax + az * az) > 110 then hi := hi + 1; end if;
  end loop;
  if hi > greatest(3, n * 0.03) then flags := array_append(flags, 'accel'); end if;
  select * into r from public.course_rules where course_id = p_course;
  if not found then
    if p_course ~ '^d[0-9]{8}$' then flags := array_append(flags, 'norules');
    else return jsonb_build_object('ok', false, 'error', 'That map doesn''t take times.'); end if;
  else
    if sqrt((a[1] - r.sx) ^ 2 + (a[3] - r.sz) ^ 2) > 8 then return jsonb_build_object('ok', false, 'error', bad); end if;
    k := (n - 1) * 8;
    if sqrt((a[k + 1] - r.fx) ^ 2 + (a[k + 3] - r.fz) ^ 2) > r.gate_r + 10 or abs(a[k + 2] - r.fy) > 15 then
      return jsonb_build_object('ok', false, 'error', bad);
    end if;
    if p_time_ms < r.floor_ms then return jsonb_build_object('ok', false, 'error', 'That time is faster than the map allows.'); end if;
    -- the run passes every checkpoint along the road, in order (real runs
    -- come within 15 m of the road's edge at every one; 25 is allowed)
    if r.cps is not null then
      fr := 1;
      for j in 0..(array_length(r.cps, 1) / 3 - 1) loop
        cx := r.cps[j * 3 + 1]; cz := r.cps[j * 3 + 2]; hw := r.cps[j * 3 + 3];
        best := 1e9; bi := fr;
        for i in fr..n loop
          k := (i - 1) * 8;
          v := sqrt((a[k + 1] - cx) ^ 2 + (a[k + 3] - cz) ^ 2);
          if v < best then best := v; bi := i; end if;
        end loop;
        if best - hw > 25 then
          return jsonb_build_object('ok', false, 'error', 'The run''s recording doesn''t follow the road, so it can''t go on the leaderboard.');
        end if;
        fr := bi;
      end loop;
    end if;
    if r.ref_ms is not null and p_time_ms < r.ref_ms * 0.9 then flags := array_append(flags, 'fast'); end if;
  end if;
  return jsonb_build_object('ok', true, 'flags', to_jsonb(flags));
end $$;

-- A best only ever gets faster, and only from a finished, counted run
-- ticket with a recording that checks out (_ghost_check). Anything unusual
-- about it is noted for the admin. Returns {improved:false, serverMs} when
-- the server already holds a faster (or equal) run.
drop function if exists public.submit_best(text, integer, text);
drop function if exists public.submit_best(text, integer, text, smallint);
create or replace function public.submit_best(p_course text, p_time_ms integer, p_samples text, p_v smallint, p_run uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare p public.profiles := public._player(); cur integer; r public.runs; g jsonb; flags text[]; top integer;
begin
  if coalesce(p_course, '') !~ '^[a-z0-9]{1,16}$' or p_time_ms is null or p_time_ms <= 0 or p_time_ms >= 600000 then
    raise exception 'bad time' using errcode = '22023';
  end if;
  select * into r from public.runs where id = p_run and uid = p.id for update;
  if not found or r.course_id <> p_course or r.status <> 'done' or not r.counted or r.best_used
     or r.time_ms <> p_time_ms or r.ended_at < now() - interval '10 minutes' then
    raise exception 'This time isn''t from a finished run on this map.' using errcode = 'P0001';
  end if;
  if p_course ~ '^d[0-9]{8}$' and not public._daily_accepts(substr(p_course, 2)) then
    raise exception 'The daily map has closed.' using errcode = 'P0001';
  end if;
  g := public._ghost_check(p_course, p_time_ms, p_samples);
  if not (g ->> 'ok')::boolean then raise exception '%', g ->> 'error' using errcode = 'P0001'; end if;
  flags := array(select jsonb_array_elements_text(g -> 'flags'));
  update public.runs set best_used = true where id = r.id;
  select time_ms into cur from public.bests where uid = p.id and course_id = p_course for update;
  if cur is not null and cur <= p_time_ms then
    return jsonb_build_object('improved', false, 'serverMs', cur);
  end if;
  -- a new record by a wide margin is worth a look (not on dailies: the
  -- first good time of the day beats nothing)
  if p_course !~ '^d[0-9]{8}$' then
    select min(time_ms) into top from public.bests where course_id = p_course and uid <> p.id and not banned;
    if top is not null and p_time_ms < top * 0.98 then flags := array_append(flags, 'record'); end if;
  end if;
  insert into public.bests (uid, course_id, display_name, banned, time_ms, updated_ms)
  values (p.id, p_course, p.display_name, p.banned, p_time_ms, (extract(epoch from now()) * 1000)::bigint)
  on conflict (uid, course_id) do update
    set time_ms = excluded.time_ms, updated_ms = excluded.updated_ms, display_name = excluded.display_name, banned = excluded.banned;
  insert into public.ghosts (uid, course_id, time_ms, samples, v) values (p.id, p_course, p_time_ms, p_samples, least(greatest(coalesce(p_v, 2), 1), 99))
  on conflict (uid, course_id) do update set time_ms = excluded.time_ms, samples = excluded.samples, v = excluded.v;
  if cardinality(flags) > 0 then
    insert into public.best_flags (uid, course_id, time_ms, flags, run_id) values (p.id, p_course, p_time_ms, flags, r.id)
      on conflict (uid, course_id) do update set time_ms = excluded.time_ms, flags = excluded.flags, run_id = excluded.run_id, at = now();
  else
    delete from public.best_flags where uid = p.id and course_id = p_course;
  end if;
  return jsonb_build_object('improved', true);
end $$;

-- Account limits: each computer may create 5 accounts, each network 30 an
-- hour, everyone together 200 an hour; a blocked computer, browser or
-- network creates none. (Signing in to accounts that already exist is
-- never limited.)
drop function if exists public.claim_profile(text, text);
create or replace function public.claim_profile(p_name text, p_code text, p_device text, p_fp text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  me uuid := auth.uid();
  email text := lower(coalesce(auth.jwt() ->> 'email', ''));
  leg public.profiles;
  inv text;
  typed text := coalesce(p_code, '');
  v_ip text := public._client_ip();
  v_fp text := left(coalesce(p_fp, ''), 64);
  why text;
  ref_by uuid;
begin
  if me is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if exists (select 1 from public.profiles where id = me) then
    return jsonb_build_object('ok', true, 'existing', true);
  end if;
  if coalesce(p_name, '') !~ '^[A-Za-z0-9_-]{3,14}$' or email <> public.login_email(p_name) then
    return jsonb_build_object('ok', false, 'error', 'name');
  end if;
  perform pg_advisory_xact_lock(hashtext('signup'));
  if coalesce(p_device, '') !~ '^[a-f0-9]{32}$' then why := 'device';
  elsif public._blocked(p_device, v_fp, v_ip) then why := 'blocked';
  elsif (select count(*) from public.signup_log where device_id = p_device) >= 5 then why := 'device_limit';
  elsif v_ip <> '' and (select count(*) from public.signup_log where ip = v_ip and at > now() - interval '1 hour') >= 30 then why := 'busy';
  elsif (select count(*) from public.signup_log where at > now() - interval '1 hour') >= 200 then why := 'busy';
  end if;
  if why is null then
    select * into leg from public.profiles where legacy and lower(display_name) = lower(p_name) for update;
    if found then
      perform public._adopt(leg.id, me, leg.display_name);          -- their name as it always was
      perform public._see_device(p_device, v_fp);
      return jsonb_build_object('ok', true, 'adopted', true);
    end if;
    if exists (select 1 from public.profiles where lower(display_name) = lower(p_name)) then
      return jsonb_build_object('ok', false, 'error', 'taken');
    end if;
    -- a friend's link ("ref:Name") counts as an invite: the friend must be a
    -- real, unbanned player, can bring at most 10 a day, and the admin can
    -- switch links off (settings 'referrals' {"on": false})
    if typed ~* '^ref:[A-Za-z0-9_-]{3,14}$' then
      if coalesce((select value ->> 'on' from public.settings where key = 'referrals'), 'true') <> 'false' then
        select id into ref_by from public.profiles where lower(display_name) = lower(substr(typed, 5)) and not banned;
      end if;
      if ref_by is null or (select count(*) from public.referrals where referrer = ref_by and at > now() - interval '1 day') >= 10 then
        why := 'invite';
      end if;
    else
      select value ->> 'code' into inv from public.settings where key = 'invite';
      if inv is null or not (trim(typed) = inv or upper(regexp_replace(typed, '\s', '', 'g')) = upper(inv)) then why := 'invite'; end if;
    end if;
  end if;
  if why is not null then
    -- the login goes too, so the name is free again
    begin delete from auth.users where id = me; exception when others then null; end;
    return jsonb_build_object('ok', false, 'error', why);
  end if;
  insert into public.profiles (id, display_name) values (me, p_name);
  if ref_by is not null then insert into public.referrals (uid, referrer) values (me, ref_by) on conflict (uid) do nothing; end if;
  insert into public.signup_log (uid, device_id, fp, ip) values (me, p_device, v_fp, v_ip);
  perform public._see_device(p_device, v_fp);
  return jsonb_build_object('ok', true);
end $$;

-- a player's counted finishes today (the day turns at midnight Pacific)
create or replace function public._day_runs(p_uid uuid) returns integer
language sql stable security definer set search_path = public, pg_temp as $$
  select count(*)::int from public.runs
  where uid = p_uid and counted
    and ended_at >= ((now() at time zone 'America/Los_Angeles')::date)::timestamp at time zone 'America/Los_Angeles'
$$;
-- the daily challenge for the calling player: finishes today, and whether today's 300 is paid
create or replace function public.my_day() returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare p public.profiles := public._player(); d text := to_char(now() at time zone 'America/Los_Angeles', 'YYYYMMDD');
begin
  return jsonb_build_object('runs', public._day_runs(p.id),
    'paid', exists (select 1 from public.credit_events where uid = p.id and kind = 'daily_runs' and note = 'day ' || d));
end $$;

-- other players' credit balances, for their profile card, trophy room and
-- the menu's leader cars (up to 40 at a time)
create or replace function public.public_credits(p_uids uuid[]) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare p public.profiles := public._player(); out jsonb := '{}'::jsonb; u uuid;
begin
  if coalesce(array_length(p_uids, 1), 0) > 40 then raise exception 'too many'; end if;
  foreach u in array coalesce(p_uids, '{}') loop
    out := out || jsonb_build_object(u::text, public._balance(u));
  end loop;
  return out;
end $$;

-- how many friends signed up from the calling player's link
create or replace function public.my_referrals() returns integer
language sql stable security definer set search_path = public, pg_temp as $$
  select count(*)::int from public.referrals where referrer = (public._player()).id
$$;

-- the +1 credit now comes only with a finished run (finish_run)
drop function if exists public.grant_credit(text);
-- races are gone from the game: their functions go too
drop function if exists public.open_lobby();
drop function if exists public.join_race(text, integer);
drop function if exists public.advance_race(text, text[]);
drop function if exists public.record_race_attempt(text, integer);


-- ------------------------------------------------------- admin: security
-- Everything the Security page shows, in one call.
create or replace function public.admin_security() returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public._require_admin();
  return jsonb_build_object(
    'flagged', coalesce((select jsonb_agg(x order by x.at desc) from (
      select f.uid, p.display_name as name, f.course_id as course, f.time_ms, f.flags, f.at, r.device_id as device, r.focus,
             (select min(b2.time_ms) from public.bests b2 where b2.course_id = f.course_id and b2.uid <> f.uid and not b2.banned) as next_ms,
             p.banned
      from public.best_flags f
      join public.bests b on b.uid = f.uid and b.course_id = f.course_id and b.time_ms = f.time_ms
      left join public.profiles p on p.id = f.uid
      left join public.runs r on r.id = f.run_id
      order by f.at desc limit 200) x), '[]'::jsonb),
    'devices', coalesce((select jsonb_agg(x order by x.last_seen desc) from (
      select d.id, d.fp, d.first_ip, d.last_ip, d.first_seen, d.last_seen,
             (select count(*) from public.signup_log s where s.device_id = d.id) as created,
             (select coalesce(jsonb_agg(pp.display_name order by pp.display_name), '[]'::jsonb)
                from public.device_accounts da join public.profiles pp on pp.id = da.uid where da.device_id = d.id) as names,
             (select count(*) from public.devices d2 where d2.fp = d.fp and d.fp <> '') as same_fp,
             exists (select 1 from public.bans b where b.kind = 'device' and b.value = d.id) as banned,
             exists (select 1 from public.bans b where b.kind = 'fp' and b.value = d.fp) as fp_banned,
             (select count(*) from public.runs r where r.device_id = d.id and r.started_at > now() - interval '24 hours') as runs_24h
      from public.devices d order by d.last_seen desc limit 300) x), '[]'::jsonb),
    'bans', coalesce((select jsonb_agg(b order by b.created_at desc) from public.bans b), '[]'::jsonb),
    'held', coalesce((select jsonb_agg(x order by x.day desc) from (
      select dr.day, dr.uid, dr.display_name as name, dr.time_ms,
             (select f.flags from public.best_flags f where f.uid = dr.uid and f.course_id = 'd' || dr.day) as flags
      from public.daily_results dr where dr.held and dr.paid is not true) x), '[]'::jsonb),
    'stats', jsonb_build_object(
      'signups24h', (select count(*) from public.signup_log where at > now() - interval '24 hours'),
      'runs1h', (select count(*) from public.runs where started_at > now() - interval '1 hour'),
      'devices', (select count(*) from public.devices),
      'bans', (select count(*) from public.bans)));
end $$;

create or replace function public.admin_ban(p_kind text, p_value text, p_note text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public._require_admin();
  if p_kind not in ('device', 'fp', 'ip') or coalesce(btrim(p_value), '') = '' then raise exception 'bad ban' using errcode = '22023'; end if;
  insert into public.bans (kind, value, note) values (p_kind, btrim(p_value), left(coalesce(p_note, ''), 200))
    on conflict (kind, value) do update set note = excluded.note;
  -- a blocked computer's open runs end now
  if p_kind = 'device' then update public.runs set status = 'void' where device_id = btrim(p_value) and status = 'open'; end if;
end $$;
create or replace function public.admin_unban(p_kind text, p_value text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public._require_admin();
  delete from public.bans where kind = p_kind and value = p_value;
end $$;
-- the time is fine: drop its flags
create or replace function public.admin_clear_flags(p_uid uuid, p_course text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public._require_admin();
  delete from public.best_flags where uid = p_uid and course_id = p_course;
end $$;
-- the time is not fine: it goes, with its ghost
create or replace function public.admin_remove_best(p_uid uuid, p_course text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public._require_admin();
  delete from public.bests where uid = p_uid and course_id = p_course;
  delete from public.ghosts where uid = p_uid and course_id = p_course;
  delete from public.best_flags where uid = p_uid and course_id = p_course;
end $$;
-- a held daily: pay the winner, or refuse (the time is removed and nobody
-- is paid for that day)
create or replace function public.admin_release_daily(p_day text, p_pay boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare r public.daily_results;
begin
  perform public._require_admin();
  select * into r from public.daily_results where day = p_day and held and paid is not true for update;
  if not found then raise exception 'Nothing held for that day.' using errcode = 'P0001'; end if;
  if p_pay then
    insert into public.credit_events (uid, delta, kind, note) values (r.uid, 1000, 'daily_win', 'won daily ' || p_day);
    update public.daily_results set held = false, paid = true where day = p_day;
  else
    delete from public.bests where uid = r.uid and course_id = 'd' || p_day;
    delete from public.ghosts where uid = r.uid and course_id = 'd' || p_day;
    update public.daily_results set held = false, paid = false where day = p_day;
  end if;
end $$;
-- the Cloudflare Turnstile site key the game shows on sign-up and sign-in
create or replace function public.admin_set_captcha(p_site text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare v text := btrim(coalesce(p_site, ''));
begin
  perform public._require_admin();
  if v <> '' and v !~ '^[A-Za-z0-9_-]{8,100}$' then raise exception 'That doesn''t look like a Turnstile site key.' using errcode = '22023'; end if;
  insert into public.settings (key, value) values ('captcha', jsonb_build_object('site', v))
    on conflict (key) do update set value = excluded.value;
  return jsonb_build_object('site', v);
end $$;

-- the run history fills at most 40 rows a minute per player (a script
-- can't flood it)
create or replace function public._run_log_limit() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if (select count(*) from public.run_log where uid = new.uid and created_at > now() - interval '1 minute') >= 40 then return null; end if;
  return new;
end $$;
drop trigger if exists run_log_limit on public.run_log;
create trigger run_log_limit before insert on public.run_log for each row execute function public._run_log_limit();

-- ---------------------------------------------------------------- admin

create or replace function public._require_admin() returns void
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if not public.is_admin() then raise exception 'admins only' using errcode = '42501'; end if;
end $$;

-- every player with their balance and real name, in one query
create or replace function public.admin_players() returns table (
  id uuid, display_name text, banned boolean, legacy boolean, created_at timestamptz, credits integer, real_name text)
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public._require_admin();
  return query
    select p.id, p.display_name, p.banned, p.legacy, p.created_at,
           coalesce(floor(c.total + 0.000000001), 0)::integer, n.real_name
    from public.profiles p
    left join (select uid, sum(delta) as total from public.credit_events group by uid) c on c.uid = p.id
    left join public.admin_notes n on n.uid = p.id
    order by p.display_name;
end $$;

create or replace function public.admin_credit_totals() returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  perform public._require_admin();
  return (select jsonb_build_object(
    'earned', coalesce(sum(delta) filter (where delta > 0), 0),
    'spent', coalesce(-sum(delta) filter (where delta < 0), 0)) from public.credit_events);
end $$;

create or replace function public.admin_set_credits(p_uid uuid, p_target integer) returns integer
language plpgsql security definer set search_path = public, pg_temp as $$
declare live numeric;
begin
  perform public._require_admin();
  if p_target is null or p_target < 0 or p_target > 1000000000 then raise exception 'bad amount' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtext('credits:' || p_uid::text));
  select coalesce(sum(delta), 0) into live from public.credit_events where uid = p_uid;
  if live <> p_target then
    insert into public.credit_events (uid, delta, kind, note) values (p_uid, p_target - live, 'adjust', 'admin set to ' || p_target);
  end if;
  return public._balance(p_uid);
end $$;

create or replace function public.admin_set_banned(p_uid uuid, p_banned boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public._require_admin();
  update public.profiles set banned = p_banned where id = p_uid;
  update public.bests set banned = p_banned where uid = p_uid;
end $$;

-- a new password for a player who forgot theirs (logins have no inbox, so
-- there is no reset email); bcrypt, the same as Supabase's own sign-up
create or replace function public.admin_set_password(p_uid uuid, p_password text) returns void
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
begin
  perform public._require_admin();
  if length(coalesce(p_password, '')) < 6 then raise exception 'Use at least 6 characters.' using errcode = 'P0001'; end if;
  update auth.users set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf')), updated_at = now()
    where id = p_uid;
  if not found then
    raise exception 'That player has no login yet (they have not signed up since the move).' using errcode = 'P0001';
  end if;
end $$;

-- removes a player completely, login included
create or replace function public.admin_delete_player(p_uid uuid) returns integer
language plpgsql security definer set search_path = public, pg_temp as $$
declare n integer := 0; added integer;
begin
  perform public._require_admin();
  delete from public.bests where uid = p_uid; get diagnostics added = row_count; n := n + added;
  delete from public.ghosts where uid = p_uid; get diagnostics added = row_count; n := n + added;
  delete from public.credit_events where uid = p_uid; get diagnostics added = row_count; n := n + added;
  delete from public.run_log where uid = p_uid; get diagnostics added = row_count; n := n + added;
  delete from public.race_entries where uid = p_uid; get diagnostics added = row_count; n := n + added;
  delete from public.car_customization where uid = p_uid; get diagnostics added = row_count; n := n + added;
  delete from public.admin_notes where uid = p_uid; get diagnostics added = row_count; n := n + added;
  delete from public.admins where user_id = p_uid;
  -- (Supabase refuses any UPDATE or DELETE without a WHERE of its own)
  update public.season_awards set data = (
    select coalesce(jsonb_object_agg(key, value), '{}') from jsonb_each(data) where value ->> 'uid' is distinct from p_uid::text)
    where data::text like '%' || p_uid::text || '%';
  delete from public.profiles where id = p_uid; get diagnostics added = row_count; n := n + added;
  update public.legacy_ids set deleted = true where new_id = p_uid;
  begin delete from auth.users where id = p_uid; exception when others then null; end;
  return n;
end $$;

-- Loads one chunk of a Firebase export or a backup (the admin page sends it
-- in parts), and says how many rows were added. Safe to run again: nothing
-- is duplicated, and a faster time is never replaced by a slower one. A
-- player who already signed up again under their old name gets their old
-- data straight away.
create or replace function public.admin_import(p jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r jsonb;
  id_of uuid;
  counts jsonb := '{}';
  n integer;
  added integer;
begin
  perform public._require_admin();

  -- players first, so everything else can be mapped to them
  n := 0;
  for r in select * from jsonb_array_elements(coalesce(p -> 'profiles', '[]')) loop
    if coalesce(r ->> 'id', '') = '' or coalesce(r ->> 'displayName', '') = '' then continue; end if;
    if exists (select 1 from public.legacy_ids where old_uid = r ->> 'id' and deleted) then continue; end if;
    select new_id into id_of from public.legacy_ids where old_uid = r ->> 'id';
    if id_of is null then
      -- already back under a new login? then that login is who this is
      select pr.id into id_of from public.profiles pr where lower(pr.display_name) = lower(r ->> 'displayName') and not pr.legacy;
      insert into public.legacy_ids (old_uid, new_id) values (r ->> 'id', coalesce(id_of, gen_random_uuid()))
        on conflict (old_uid) do nothing;
      select new_id into id_of from public.legacy_ids where old_uid = r ->> 'id';
    end if;
    if not exists (select 1 from public.profiles where id = id_of) then
      insert into public.profiles (id, display_name, banned, legacy, created_at)
      values (id_of, r ->> 'displayName', coalesce((r ->> 'banned')::boolean, false), true,
              coalesce(to_timestamp((r ->> 'createdAt')::numeric / 1000), now()))
      on conflict do nothing;
      get diagnostics added = row_count; n := n + added;
    end if;
  end loop;
  counts := counts || jsonb_build_object('profiles', n);

  n := 0;
  for r in select * from jsonb_array_elements(coalesce(p -> 'bests', '[]')) loop
    select new_id into id_of from public.legacy_ids where old_uid = r ->> 'uid' and not deleted;
    if id_of is null or (r ->> 'timeMs') is null then continue; end if;
    insert into public.bests (uid, course_id, display_name, banned, time_ms, updated_ms)
    values (id_of, r ->> 'courseId', coalesce(r ->> 'displayName', 'Driver'), coalesce((r ->> 'banned')::boolean, false),
            round((r ->> 'timeMs')::numeric)::integer, coalesce((r ->> 'updatedMs')::numeric, 0)::bigint)
    on conflict (uid, course_id) do update
      set time_ms = excluded.time_ms, updated_ms = excluded.updated_ms
      where excluded.time_ms < public.bests.time_ms;
    get diagnostics added = row_count; n := n + added;
  end loop;
  counts := counts || jsonb_build_object('bests', n);

  n := 0;
  for r in select * from jsonb_array_elements(coalesce(p -> 'ghosts', '[]')) loop
    select new_id into id_of from public.legacy_ids where old_uid = r ->> 'uid' and not deleted;
    if id_of is null or coalesce(r ->> 'samples', '') = '' or length(r ->> 'samples') >= 400000 then continue; end if;
    insert into public.ghosts (uid, course_id, time_ms, samples, v)
    values (id_of, r ->> 'courseId', round((r ->> 'timeMs')::numeric)::integer, r ->> 'samples', coalesce((r ->> 'v')::smallint, 1))
    on conflict (uid, course_id) do update
      set time_ms = excluded.time_ms, samples = excluded.samples, v = excluded.v
      where excluded.time_ms < public.ghosts.time_ms;
    get diagnostics added = row_count; n := n + added;
  end loop;
  counts := counts || jsonb_build_object('ghosts', n);

  n := 0;
  for r in select * from jsonb_array_elements(coalesce(p -> 'creditEvents', '[]')) loop
    select new_id into id_of from public.legacy_ids where old_uid = r ->> 'uid' and not deleted;
    if id_of is null or jsonb_typeof(r -> 'delta') <> 'number' then continue; end if;
    insert into public.credit_events (uid, delta, kind, race_id, note, legacy_id, created_at)
    values (id_of, (r ->> 'delta')::numeric,
            coalesce(r ->> 'kind', substring(r ->> 'id' from '_([a-z]+)$'), 'legacy'),
            r ->> 'raceId', r ->> 'note', r ->> 'id',
            coalesce(to_timestamp((r ->> 'createdAt')::numeric / 1000), now()))
    on conflict (legacy_id) do nothing;
    get diagnostics added = row_count; n := n + added;
  end loop;
  counts := counts || jsonb_build_object('creditEvents', n);

  n := 0;
  for r in select * from jsonb_array_elements(coalesce(p -> 'carCustomization', '[]')) loop
    select new_id into id_of from public.legacy_ids where old_uid = coalesce(r ->> 'uid', r ->> 'id') and not deleted;
    if id_of is null or not public.valid_hsl(r -> 'primary') or not public.valid_hsl(r -> 'secondary') then continue; end if;
    -- A player who signed up before the import already has starter
    -- colours: their old ones join the list and are put back on the car.
    -- Once merged, the old list is contained in theirs, so a repeat import
    -- leaves whatever they have chosen since alone.
    insert into public.car_customization (uid, unlocked, primary_color, secondary_color)
    values (id_of, coalesce(r -> 'unlocked', '[]'), r -> 'primary', r -> 'secondary')
    on conflict (uid) do update
      set unlocked = (select coalesce(jsonb_agg(distinct x), '[]') from (
            select jsonb_array_elements(excluded.unlocked) x
            union select jsonb_array_elements(public.car_customization.unlocked)) u),
          primary_color = excluded.primary_color, secondary_color = excluded.secondary_color, updated_at = now()
      where not (public.car_customization.unlocked @> excluded.unlocked);
    get diagnostics added = row_count; n := n + added;
  end loop;
  counts := counts || jsonb_build_object('carCustomization', n);

  n := 0;
  for r in select * from jsonb_array_elements(coalesce(p -> 'adminNotes', '[]')) loop
    select new_id into id_of from public.legacy_ids where old_uid = r ->> 'id' and not deleted;
    if id_of is null or coalesce(r ->> 'realName', '') = '' then continue; end if;
    insert into public.admin_notes (uid, real_name) values (id_of, r ->> 'realName') on conflict (uid) do nothing;
    get diagnostics added = row_count; n := n + added;
  end loop;
  counts := counts || jsonb_build_object('adminNotes', n);

  n := 0;
  for r in select * from jsonb_array_elements(coalesce(p -> 'runLog', '[]')) loop
    select new_id into id_of from public.legacy_ids where old_uid = r ->> 'uid' and not deleted;
    if id_of is null then continue; end if;
    insert into public.run_log (uid, display_name, kind, course_id, outcome, time_ms, data, legacy_id, created_at)
    values (id_of, r ->> 'displayName', r ->> 'kind', r ->> 'courseId', r ->> 'outcome',
            round(coalesce((r ->> 'timeMs')::numeric, 0))::integer,
            r - 'uid' - 'displayName' - 'kind' - 'courseId' - 'outcome' - 'timeMs' - 'createdAt' - 'id',
            r ->> 'id', coalesce(to_timestamp((r ->> 'createdAt')::numeric / 1000), now()))
    on conflict (legacy_id) do nothing;
    get diagnostics added = row_count; n := n + added;
  end loop;
  counts := counts || jsonb_build_object('runLog', n);

  -- season awards: each placing's uid mapped to its new id (a deleted
  -- player's place is left out)
  for r in select * from jsonb_array_elements(coalesce(p -> 'seasonAwards', '[]')) loop
    insert into public.season_awards (season, data)
    select r ->> 'id', coalesce(jsonb_object_agg(k, v || jsonb_build_object('uid',
             coalesce((select new_id::text from public.legacy_ids where old_uid = v ->> 'uid'), v ->> 'uid'))), '{}')
      from jsonb_each(r - 'id') as t(k, v) where jsonb_typeof(v) = 'object'
        and not exists (select 1 from public.legacy_ids d where d.old_uid = v ->> 'uid' and d.deleted)
    on conflict (season) do nothing;                 -- trophies changed since the first import stay
  end loop;

  if p ? 'invite' and coalesce(p -> 'invite' ->> 'code', '') <> '' then
    insert into public.settings (key, value) values ('invite', jsonb_build_object('code', p -> 'invite' ->> 'code'))
    on conflict (key) do nothing;
  end if;
  if p ? 'adminPasscode' and coalesce(p -> 'adminPasscode' ->> 'passHash', '') <> '' then
    insert into public.settings (key, value)
    values ('admin_passcode', jsonb_build_object('salt', p -> 'adminPasscode' ->> 'salt', 'passHash', p -> 'adminPasscode' ->> 'passHash'))
    on conflict (key) do nothing;
  end if;
  return counts;
end $$;

-- the messages the admin writes for the game's menu and sign-in screen;
-- anyone may read them (the sign-in screen shows before any login)
create or replace function public.get_notice() returns jsonb
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((select value from public.settings where key = 'notice'), '{}'::jsonb)
    || jsonb_build_object('captcha', coalesce((select value ->> 'site' from public.settings where key = 'captcha'), ''))
$$;
create or replace function public.admin_set_notice(p_menu text, p_login text) returns jsonb
language plpgsql volatile security definer set search_path = public, pg_temp as $$
declare v jsonb;
begin
  perform public._require_admin();
  v := jsonb_build_object('menu', left(btrim(coalesce(p_menu, '')), 600), 'login', left(btrim(coalesce(p_login, '')), 600),
                          'updatedMs', public.server_ms());
  insert into public.settings (key, value) values ('notice', v)
    on conflict (key) do update set value = excluded.value;
  return v;
end $$;

-- ---------------------------------------------------- row level security

alter table public.admins enable row level security;
alter table public.settings enable row level security;
alter table public.profiles enable row level security;
alter table public.bests enable row level security;
alter table public.ghosts enable row level security;
alter table public.credit_events enable row level security;
alter table public.car_customization enable row level security;
alter table public.run_log enable row level security;
alter table public.season_awards enable row level security;
alter table public.referrals enable row level security;
alter table public.admin_notes enable row level security;
alter table public.races enable row level security;
alter table public.race_entries enable row level security;
alter table public.legacy_ids enable row level security;
-- no policies: only the functions above ever touch these
alter table public.admin_sessions enable row level security;
alter table public.admin_login_fails enable row level security;

do $$
declare t text;
begin
  -- admins may read and change everything directly
  foreach t in array array['admins', 'settings', 'profiles', 'bests', 'ghosts', 'credit_events', 'car_customization',
                          'run_log', 'season_awards', 'admin_notes', 'races', 'race_entries', 'legacy_ids', 'referrals',
                          'daily_entries', 'daily_results', 'course_rules', 'devices', 'device_accounts', 'signup_log',
                          'bans', 'runs', 'best_flags'] loop
    execute format('drop policy if exists admin_all on public.%I', t);
    execute format('create policy admin_all on public.%I for all to anon, authenticated using (public.is_admin()) with check (public.is_admin())', t);
  end loop;
  -- signed-in players may read the shared game data
  foreach t in array array['profiles', 'bests', 'ghosts', 'car_customization', 'season_awards', 'races', 'race_entries', 'daily_results'] loop
    execute format('drop policy if exists player_read on public.%I', t);
    execute format('create policy player_read on public.%I for select to authenticated using (true)', t);
  end loop;
end $$;

drop policy if exists own_admin_row on public.admins;
create policy own_admin_row on public.admins for select to authenticated using (user_id = auth.uid());

drop policy if exists own_credits on public.credit_events;
create policy own_credits on public.credit_events for select to authenticated using (uid = auth.uid());

-- a player writes only their own colours, in the right shape
drop policy if exists own_colors_insert on public.car_customization;
create policy own_colors_insert on public.car_customization for insert to authenticated
  with check (uid = auth.uid() and public.valid_hsl(primary_color) and public.valid_hsl(secondary_color)
              and jsonb_typeof(unlocked) = 'array' and jsonb_array_length(unlocked) <= 500);
drop policy if exists own_colors_update on public.car_customization;
create policy own_colors_update on public.car_customization for update to authenticated
  using (uid = auth.uid())
  with check (uid = auth.uid() and public.valid_hsl(primary_color) and public.valid_hsl(secondary_color)
              and jsonb_typeof(unlocked) = 'array' and jsonb_array_length(unlocked) <= 500);

-- every attempt is logged by the player's own game
drop policy if exists own_run_insert on public.run_log;
create policy own_run_insert on public.run_log for insert to authenticated
  with check (uid = auth.uid() and kind in ('campaign', 'creditsrun', 'race', 'daily')
              and time_ms > 0 and time_ms < 600000
              and (outcome is null or outcome in ('finished', 'restarted', 'terminated')));

-- table access for the API roles (the policies above decide the rows).
-- The admin page is not signed in as a player, so it reaches the tables as
-- anon; every table has row level security, and for anon only the admin
-- policy (a valid admin token) lets any row through.
do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;
grant usage on schema public to anon, authenticated;
revoke all on all tables in schema public from anon;
grant select, insert, update, delete on all tables in schema public to anon, authenticated;
revoke all on public.admin_sessions, public.admin_login_fails, public.admin_accounts from anon, authenticated;
grant usage, select on all sequences in schema public to anon, authenticated;

-- functions: signed-in players (each one checks its own rules); the admin
-- page's functions check the admin token themselves
revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated;
grant execute on function public.returning_player(text) to anon;
grant execute on function public.admin_login(text, text), public.admin_logout(), public.is_admin(),
  public.get_notice(), public.admin_set_notice(text, text), public._require_admin(), public._token_hash(text),
  public.server_ms(), public.admin_players(), public.admin_credit_totals(), public.admin_set_credits(uuid, integer),
  public.admin_set_banned(uuid, boolean), public.admin_set_password(uuid, text), public.admin_delete_player(uuid),
  public.admin_import(jsonb), public.admin_security(), public.admin_ban(text, text, text), public.admin_unban(text, text),
  public.admin_clear_flags(uuid, text), public.admin_remove_best(uuid, text), public.admin_release_daily(text, boolean),
  public.admin_set_captcha(text), public._client_ip() to anon;
-- only the database owner (you, in the SQL Editor) sets the admin login,
-- and the internal device helpers are not for calling directly
revoke execute on function public.admin_set_login(text, text) from public, anon, authenticated;
revoke execute on function public.close_season(text, text[]) from public, anon, authenticated;
revoke execute on function public._day_runs(uuid) from public, anon, authenticated;
revoke execute on function public._see_device(text, text), public._blocked(text, text, text) from public, anon, authenticated;

-- ------------------------------------------------------------- season 1, closed
-- Season 2 went live on 2026-10-10. The first run of this file after that
-- keeps Season 1's final podium for good (its maps are the s2c* ids below);
-- after that the row exists and this does nothing.
do $$
begin
  if not exists (select 1 from public.season_awards where season = 'final:Season 1'
                 and jsonb_array_length(coalesce(data -> 'podium', '[]'::jsonb)) > 0) then
    perform public.close_season('Season 1', array['s2c1', 's2c29', 's2c18', 's2c4', 's2c19', 's2c6', 's2c20', 's2c26',
      's2c21', 's2c33', 's2c27', 's2c22', 's2c23', 's2c14', 's2c31', 's2c16']);
  end if;
end $$;

-- ------------------------------------------------------------- live updates
-- The game follows these tables as they change (leaderboards, balances,
-- races). Deletions carry the whole old row so boards can drop it.
alter table public.bests replica identity full;
alter table public.race_entries replica identity full;
do $$
declare t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
  foreach t in array array['bests', 'credit_events', 'races', 'race_entries'] loop
    begin
      execute format('alter publication supabase_realtime add table public.%I', t);
    exception when duplicate_object then null;
    end;
  end loop;
end $$;

-- ---------------------------------------------------------- admin access
-- The admin page signs in with the login in admin_accounts. Set it (this
-- also removes every other admin login) by running, in the SQL Editor:
--   select public.admin_set_login('your-username', 'your password of 12+ characters');
-- Game accounts are never admins.
